-- Read-only inspection. BLOCKED is not permission to apply; 01_apply repeats these checks and raises.
USE alrowad_uni_rust;
SELECT CASE WHEN DATABASE()='alrowad_uni_rust' AND EXISTS(SELECT 1 FROM academic_catalog_control WHERE control_id=1 AND schema_version=1 AND is_ready=1) AND EXISTS(SELECT 1 FROM academic_plan_control WHERE control_id=1 AND schema_version=1 AND is_ready=1)
AND EXISTS(SELECT 1 FROM information_schema.triggers WHERE trigger_schema=DATABASE() AND trigger_name='sc_cat_courses_u' AND event_object_table='courses' AND event_manipulation='UPDATE' AND action_timing='BEFORE' AND REGEXP_REPLACE(TRIM(action_statement),'[[:space:]]+',' ') IN ('BEGIN CALL sc_catalog_touch(); IF (NOT(NEW.course_code<=>OLD.course_code) OR NOT(NEW.credit_hours<=>OLD.credit_hours) OR NOT(NEW.theoretical_hours<=>OLD.theoretical_hours) OR NOT(NEW.practical_hours<=>OLD.practical_hours) OR NOT(NEW.is_active<=>OLD.is_active)) AND (sc_catalog_course_used(OLD.course_id)) THEN SIGNAL SQLSTATE ''45000'' SET MESSAGE_TEXT=''academic_catalog_history_locked''; END IF; END','BEGIN CALL sc_catalog_touch(); IF (NOT(NEW.course_code<=>OLD.course_code) OR NOT(NEW.credit_hours<=>OLD.credit_hours) OR NOT(NEW.theoretical_hours<=>OLD.theoretical_hours) OR NOT(NEW.practical_hours<=>OLD.practical_hours) OR NOT(NEW.is_active<=>OLD.is_active)) AND (sc_catalog_course_used(OLD.course_id)) AND NOT ((NEW.course_name<=>OLD.course_name) AND (NEW.credit_hours<=>OLD.credit_hours) AND (NEW.theoretical_hours<=>OLD.theoretical_hours) AND (NEW.practical_hours<=>OLD.practical_hours) AND (NEW.is_active<=>OLD.is_active) AND (NEW.description<=>OLD.description) AND sc_completion_code_allowed(OLD.course_id,OLD.course_code,NEW.course_code)) THEN SIGNAL SQLSTATE ''45000'' SET MESSAGE_TEXT=''academic_catalog_history_locked''; END IF; END'))
AND EXISTS(SELECT 1 FROM information_schema.triggers WHERE trigger_schema=DATABASE() AND trigger_name='sc_plan_course_u' AND event_object_table='courses' AND event_manipulation='UPDATE' AND action_timing='BEFORE' AND REGEXP_REPLACE(TRIM(action_statement),'[[:space:]]+',' ') IN ('BEGIN CALL sc_plan_touch(); IF sc_plan_fixed_course(OLD.course_id) AND (NOT(NEW.course_code<=>OLD.course_code) OR NOT(NEW.credit_hours<=>OLD.credit_hours) OR NOT(NEW.theoretical_hours<=>OLD.theoretical_hours) OR NOT(NEW.practical_hours<=>OLD.practical_hours) OR NOT(NEW.is_active<=>OLD.is_active)) THEN SIGNAL SQLSTATE ''45000'' SET MESSAGE_TEXT=''academic_catalog_history_locked''; END IF; END','BEGIN CALL sc_plan_touch(); IF sc_plan_fixed_course(OLD.course_id) AND (NOT(NEW.course_code<=>OLD.course_code) OR NOT(NEW.credit_hours<=>OLD.credit_hours) OR NOT(NEW.theoretical_hours<=>OLD.theoretical_hours) OR NOT(NEW.practical_hours<=>OLD.practical_hours) OR NOT(NEW.is_active<=>OLD.is_active)) AND NOT ((NEW.course_name<=>OLD.course_name) AND (NEW.credit_hours<=>OLD.credit_hours) AND (NEW.theoretical_hours<=>OLD.theoretical_hours) AND (NEW.practical_hours<=>OLD.practical_hours) AND (NEW.is_active<=>OLD.is_active) AND (NEW.description<=>OLD.description) AND sc_completion_code_allowed(OLD.course_id,OLD.course_code,NEW.course_code)) THEN SIGNAL SQLSTATE ''45000'' SET MESSAGE_TEXT=''academic_catalog_history_locked''; END IF; END'))
AND (NOT EXISTS(SELECT 1 FROM information_schema.routines WHERE routine_schema=DATABASE() AND routine_name='sc_completion_code_allowed') OR (EXISTS(SELECT 1 FROM information_schema.routines WHERE routine_schema=DATABASE() AND routine_name='sc_completion_code_allowed' AND routine_type='FUNCTION' AND data_type='tinyint' AND REGEXP_REPLACE(TRIM(routine_definition),'[[:space:]]+',' ')='BEGIN DECLARE permit LONGTEXT DEFAULT NULL; DECLARE drawing_key INT; DECLARE chemistry_key INT; DECLARE scratch VARCHAR(50); DECLARE drawing_code VARCHAR(50); DECLARE chemistry_code VARCHAR(50); SELECT context INTO permit FROM academic_plan_events WHERE academic_plan_event_id=@catalog_completion_permit_event_id AND action=''catalog_completion_code_permit''; IF permit IS NULL THEN RETURN 0; END IF; IF COALESCE(JSON_UNQUOTE(JSON_EXTRACT(permit,''$.manifest_hash''))=''2e97008596d48323c9280aad64b07f63e1af68ecda137149c4a1d65c2bd42238'' AND JSON_EXTRACT(permit,''$.connection_id'')=CONNECTION_ID() AND JSON_UNQUOTE(JSON_EXTRACT(permit,''$.drawing_code_before''))=''FE114'' AND JSON_UNQUOTE(JSON_EXTRACT(permit,''$.chemistry_code_before''))=''FE113'' AND EXISTS(SELECT 1 FROM user_activity_logs l WHERE l.action_code=''catalog_completion.started'' AND JSON_UNQUOTE(JSON_EXTRACT(l.description,''$.operation_id''))=JSON_UNQUOTE(JSON_EXTRACT(permit,''$.operation_id'')) AND JSON_UNQUOTE(JSON_EXTRACT(l.description,''$.manifest_hash''))=JSON_UNQUOTE(JSON_EXTRACT(permit,''$.manifest_hash''))),0)=0 THEN RETURN 0; END IF; IF EXISTS(SELECT 1 FROM academic_plan_events e WHERE e.action=''catalog_completion_code_applied'' AND JSON_UNQUOTE(JSON_EXTRACT(e.context,''$.permit_event_id''))=CAST(@catalog_completion_permit_event_id AS CHAR)) THEN RETURN 0; END IF; SET drawing_key=JSON_EXTRACT(permit,''$.drawing_id''); SET chemistry_key=JSON_EXTRACT(permit,''$.chemistry_id''); SET scratch=CONCAT(''__D05_'',@catalog_completion_permit_event_id); SELECT course_code INTO drawing_code FROM courses WHERE course_id=drawing_key; SELECT course_code INTO chemistry_code FROM courses WHERE course_id=chemistry_key; RETURN COALESCE(drawing_key<>chemistry_key AND ( (course_key=drawing_key AND previous_code=''FE114'' AND next_code=scratch AND chemistry_code=''FE113'') OR (course_key=chemistry_key AND previous_code=''FE113'' AND next_code=''FE114'' AND drawing_code=scratch) OR (course_key=drawing_key AND previous_code=scratch AND next_code=''FE113'' AND chemistry_code=''FE114'')),0); END') AND (SELECT COUNT(*) FROM information_schema.parameters WHERE specific_schema=DATABASE() AND specific_name='sc_completion_code_allowed')=4 AND (SELECT COUNT(*) FROM information_schema.parameters WHERE specific_schema=DATABASE() AND specific_name='sc_completion_code_allowed' AND ((ordinal_position=0 AND data_type='tinyint') OR (ordinal_position=1 AND parameter_mode='IN' AND parameter_name='course_key' AND data_type='int') OR (ordinal_position=2 AND parameter_mode='IN' AND parameter_name='previous_code' AND data_type='varchar' AND character_maximum_length=50) OR (ordinal_position=3 AND parameter_mode='IN' AND parameter_name='next_code' AND data_type='varchar' AND character_maximum_length=50)))=4))
THEN 'READY' ELSE 'BLOCKED' END result;
